 'functions',(select jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'definition',pg_get_functiondef(p.oid),'owner',pg_get_userbyid(p.proowner),'acl',p.proacl::text) order by p.oid::regprocedure::text) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('phone_pending_readiness','learn_phone_account_evidence','learn_phone_processing_evidence','learn_operator_capture_health')),
 'indexes',(select coalesce(jsonb_agg(indexdef order by indexname),'[]') from pg_indexes where schemaname='public' and indexname='learn_phone_schedule_health_lookup'))))::text) as fingerprint,(select jsonb_agg(to_jsonb(x) order by x.name) from serviceos_phone_health_preserved x) as preserved;
commit;
